
<div
  class="dialog"
  :style="{ display: value ? 'flex' : 'none' }"
  @click.self="$emit('input', false)"
>
  <div
    class="dialog-body"
    style="max-height: 360px; overflow-y: auto;"
  >
    <div class="dialog-header" @click="$emit('input', false)">
      <h3>Signature</h3>
    </div>
    <div class="dialog-content">
      <div
        class="signature-canvas-wrapper"
        style="padding: 1px; width: 500px; height: 180px"
      >
        <canvas
          id="signature-canvas"
          width="480"
          height="180"
          style="border: 1px dashed black"
        />
      </div>
      <div style="display: flex; padding-top: 10px; justify-content: center;">
        <a class="link-button" href="#" @click.prevent="clear()">
          Clear Signature
        </a>
        <button
          class="button"
          @click="submit()"
          style="margin: 5px; margin-left: 15px"
        >
          OK
        </button>
      </div>
    </div>
  </div>
</div>
