
<button class="icon-button" v-bind="$attrs" v-on="$listeners">
  <x-icon
    type="mdi"
    :size="iconSize"
    :path="icon"
    :style="{ color: color }"
  />
  <span
    v-show="showButtonText"
    style="font-size: 16px; position: relative; top: -5px"
    :style="{ color: color }"
  >
    {{ text }}
  </span>
</button>
